// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.StoredBNodeIdResolver;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.impl.BNodeOrigins;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbStoredBNodeOriginTest {
	@TempDir
	Path temporary;

	@Test
	void persistentReloadRestoresDirectContextAndNestedStoredOrigins() {
		for (int opening = 0; opening < 2; opening++) {
			var repository = new SailRepository(new LmdbStore(temporary.toFile()));
			repository.init();
			try (var connection = repository.getConnection()) {
				var factory = repository.getValueFactory();
				if (opening == 0) {
					connection.add(factory.createBNode("persisted-subject"), factory.createIRI("urn:p"),
							factory.createTripleTerm(factory.createIRI("urn:outer"), factory.createIRI("urn:q"),
									factory.createTripleTerm(factory.createIRI("urn:inner"), factory.createIRI("urn:r"),
											factory.createBNode("persisted-nested"))),
							factory.createBNode("persisted-context"));
				} else {
					var lookup = (StoredBNodeIdResolver) factory;
					assertTrue(lookup.hasStoredBNodeId("persisted-subject"));
					assertTrue(lookup.hasStoredBNodeId("persisted-context"));
					assertTrue(lookup.hasStoredBNodeId("persisted-nested"));
					assertFalse(lookup.hasStoredBNodeId("not-stored-after-reload"));
				}
			} finally {
				repository.shutDown();
			}
		}
	}

	@Test
	void storageAdmissionIncludesNestedTermsButExcludesAllocationAndFactoryRegistration() {
		var repository = new SailRepository(new LmdbStore(temporary.toFile()));
		repository.init();
		try (var connection = repository.getConnection()) {
			var factory = repository.getValueFactory();
			var lookup = (StoredBNodeIdResolver) factory;
			var origins = new BNodeOrigins(factory);
			var factoryOnly = factory.createBNode("factory-only-origin");
			assertFalse(lookup.hasStoredBNodeId(factoryOnly.getID()));
			assertFalse(origins.isReference(factoryOnly));
			var plain = SimpleValueFactory.getInstance();
			var nested = plain.createBNode("nested-stored-origin");
			var predicate = plain.createIRI("urn:p");
			connection.add(plain.createIRI("urn:root"), predicate,
					plain.createTripleTerm(plain.createIRI("urn:outer"), predicate,
							plain.createTripleTerm(plain.createIRI("urn:inner"), predicate, nested)));
			assertTrue(lookup.hasStoredBNodeId(nested.getID()));
			assertTrue(new BNodeOrigins(factory).isReference(nested));

			BNode generated;
			try (var rows = connection.prepareTupleQuery("SELECT ?node WHERE { BIND(BNODE() AS ?node) }").evaluate()) {
				generated = (BNode) rows.next().getValue("node");
				assertFalse(new BNodeOrigins(factory).isReference(generated));
				assertFalse(lookup.hasStoredBNodeId(generated.getID()));
			}
			connection.add(generated, predicate, plain.createLiteral("admitted concurrently with result lifetime"));
			assertTrue(lookup.hasStoredBNodeId(generated.getID()));
			assertFalse(new BNodeOrigins(factory).isReference(generated),
					"the original query allocation retains transient provenance after its ID is admitted");
			try (var rows = connection
					.prepareTupleQuery("SELECT ?node WHERE { ?node <urn:p> ?value . FILTER(isBlank(?node)) }")
					.evaluate()) {
				assertTrue(new BNodeOrigins(factory).isReference((BNode) rows.next().getValue("node")));
			}
			try (var statements = connection.prepareGraphQuery(
					"CONSTRUCT { [] <urn:p> ?node } WHERE { VALUES ?node { <_:nested-stored-origin> } }").evaluate()) {
				var statement = statements.next();
				assertFalse(new BNodeOrigins(factory).isReference((BNode) statement.getSubject()));
				assertTrue(new BNodeOrigins(factory).isReference((BNode) statement.getObject()));
			}
		} finally {
			repository.shutDown();
		}
	}
}
